package serverinstance

import (
	"net"
	"net/url"
	"strings"
)

// Normalize returns the explicit server instance when present, otherwise a
// deterministic identity derived from baseURL's host and port.
//
// The derived identity ignores URL path components so provider endpoints that
// differ only by `/v1` root normalization still collapse to the same
// server-instance label.
func Normalize(baseURL, explicit string) string {
	if trimmed := strings.TrimSpace(explicit); trimmed != "" {
		return trimmed
	}
	return FromBaseURL(baseURL)
}

// FromBaseURL derives a stable server-instance label from the URL host/port.
func FromBaseURL(baseURL string) string {
	trimmed := strings.TrimSpace(baseURL)
	if trimmed == "" {
		return ""
	}
	parsed, err := url.Parse(trimmed)
	if err != nil {
		return fallbackHostPort(trimmed)
	}
	host := strings.TrimSpace(parsed.Hostname())
	if host == "" {
		return fallbackHostPort(trimmed)
	}
	port := strings.TrimSpace(parsed.Port())
	if port == "" {
		return host
	}
	return host + ":" + port
}

func fallbackHostPort(raw string) string {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return ""
	}
	host, port, err := net.SplitHostPort(raw)
	if err == nil && host != "" {
		if port != "" {
			return host + ":" + port
		}
		return host
	}
	raw = strings.TrimPrefix(raw, "http://")
	raw = strings.TrimPrefix(raw, "https://")
	raw = strings.TrimSuffix(raw, "/v1")
	raw = strings.TrimSuffix(raw, "/")
	return raw
}

package config

import (
	"path/filepath"
	"time"

	fizeau "github.com/DocumentDrivenDX/fizeau"
)

func init() {
	// Register the config loader into the root package so that fizeau.New can
	// load configuration without importing this package directly (which would
	// create an import cycle: config → agent → config).
	fizeau.RegisterConfigLoader(func(dir string) (fizeau.ServiceConfig, error) {
		cfg, err := Load(dir)
		if err != nil {
			return nil, err
		}
		return &configServiceConfig{cfg: cfg, baseDir: dir}, nil
	})
}

// configServiceConfig wraps a loaded *Config and satisfies fizeau.ServiceConfig.
// It is the agent-internal equivalent of DDx's ServiceConfigAdapter.
type configServiceConfig struct {
	cfg     *Config
	baseDir string
}

func NewServiceConfig(cfg *Config, baseDir string) fizeau.ServiceConfig {
	return &configServiceConfig{cfg: cfg, baseDir: baseDir}
}

func (c *configServiceConfig) ProviderNames() []string {
	if c.cfg == nil {
		return nil
	}
	return c.cfg.ProviderNames()
}

func (c *configServiceConfig) DefaultProviderName() string {
	if c.cfg == nil {
		return ""
	}
	return c.cfg.DefaultName()
}

func (c *configServiceConfig) Provider(name string) (fizeau.ServiceProviderEntry, bool) {
	if c.cfg == nil {
		return fizeau.ServiceProviderEntry{}, false
	}
	pc, ok := c.cfg.Providers[name]
	if !ok {
		return fizeau.ServiceProviderEntry{}, false
	}
	endpoints := make([]fizeau.ServiceProviderEndpoint, 0, len(pc.Endpoints))
	for _, endpoint := range pc.Endpoints {
		endpoints = append(endpoints, fizeau.ServiceProviderEndpoint{
			Name:           endpoint.Name,
			BaseURL:        endpoint.BaseURL,
			ServerInstance: endpoint.ServerInstance,
		})
	}
	return fizeau.ServiceProviderEntry{
		Type:             pc.Type,
		BaseURL:          pc.BaseURL,
		ServerInstance:   pc.ServerInstance,
		Endpoints:        endpoints,
		APIKey:           pc.APIKey,
		Model:            pc.Model,
		ConfigError:      c.cfg.ProviderError(name),
		DailyTokenBudget: pc.DailyTokenBudget,
	}, true
}

func (c *configServiceConfig) HealthCooldown() time.Duration {
	if c.cfg == nil || c.cfg.Routing.HealthCooldown == "" {
		return 0
	}
	d, err := time.ParseDuration(c.cfg.Routing.HealthCooldown)
	if err != nil {
		return 0
	}
	return d
}

func (c *configServiceConfig) WorkDir() string {
	return c.baseDir
}

func (c *configServiceConfig) SessionLogDir() string {
	workDir := c.WorkDir()
	if workDir == "" {
		return ""
	}
	return filepath.Join(workDir, ProjectConfigDirName(), "sessions")
}

package fizeau

import (
	"path/filepath"
	"sync"
	"sync/atomic"
	"time"

	agentcore "github.com/DocumentDrivenDX/fizeau/internal/core"
	"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
	"github.com/DocumentDrivenDX/fizeau/internal/session"
)

// serviceSessionLog is the service-owned writer that persists the session
// lifecycle records (session.start + session.end) for one Execute call. It
// is constructed in runExecute after the route is resolved and torn down in
// a defer on the same goroutine. Sub-paths (runNative, runSubprocess, ...)
// emit the terminal event through finalizeAndEmit, which delegates here to
// keep the session log in sync with the public event stream.
type serviceSessionLog struct {
	logger    *session.Logger
	path      string
	sessionID string
	decision  RouteDecision
	override  *overrideContext
	endOnce   sync.Once
	endWrote  atomic.Bool
	closeOnce sync.Once

	progressMu     sync.Mutex
	lastProgressAt time.Time
}

// openSessionLog creates the session-log writer for req and emits the
// session.start record. A nil-or-empty req.SessionLogDir yields a no-op
// writer so callers don't need to branch on whether logging is enabled.
func (s *service) openSessionLog(req ServiceExecuteRequest, decision RouteDecision, sessionID string) *serviceSessionLog {
	if req.SessionLogDir == "" || sessionID == "" {
		return &serviceSessionLog{}
	}
	logger := session.NewLogger(req.SessionLogDir, sessionID)
	sl := &serviceSessionLog{
		logger:    logger,
		path:      filepath.Join(req.SessionLogDir, sessionID+".jsonl"),
		sessionID: sessionID,
		decision:  decision,
	}
	// CONTRACT-003: echo top-level Role + CorrelationID into the
	// session-log header (one line per session). Top-level wins over
	// any caller Metadata entry under the reserved keys.
	headerMeta := metaWithRoleAndCorrelation(req.Metadata, req.Role, req.CorrelationID)
	start := session.SessionStartData{
		Provider:               s.providerTypeLabel(decision.Provider),
		Model:                  decision.Model,
		SelectedProvider:       decision.Provider,
		SelectedEndpoint:       decision.Endpoint,
		SelectedServerInstance: decision.ServerInstance,
		SelectedRoute:          req.SelectedRoute,
		Sticky: session.RoutingStickyState{
			KeyPresent:     req.CorrelationID != "",
			Assignment:     decision.Sticky.Assignment,
			ServerInstance: decision.Sticky.ServerInstance,
			Reason:         decision.Sticky.Reason,
		},
		Utilization: session.RoutingUtilizationState{
			Source:         decision.Utilization.Source,
			Freshness:      decision.Utilization.Freshness,
			ActiveRequests: decision.Utilization.ActiveRequests,
			QueuedRequests: decision.Utilization.QueuedRequests,
			MaxConcurrency: decision.Utilization.MaxConcurrency,
			CachePressure:  decision.Utilization.CachePressure,
			ObservedAt:     decision.Utilization.ObservedAt,
		},
		RequestedHarness:  req.Harness,
		ResolvedHarness:   decision.Harness,
		HarnessSource:     harnessSource(req),
		RequestedModel:    req.Model,
		RequestedModelRef: req.ModelRef,
		ResolvedModelRef:  req.ResolvedModelRef,
		ResolvedModel:     decision.Model,
		Reasoning:         req.Reasoning,
		WorkDir:           req.WorkDir,
		MaxIterations:     req.MaxIterations,
		Prompt:            req.Prompt,
		SystemPrompt:      req.SystemPrompt,
		Metadata:          headerMeta,
	}
	logger.Emit(agentcore.EventSessionStart, start)
	return sl
}

// writeEnd records the terminal session.end event. It is idempotent: the
// first call wins. Callers should invoke this whenever a harnesses.FinalData
// is produced — finalizeAndEmit threads it together with the public-stream
// emit so the two views stay consistent.
func (sl *serviceSessionLog) writeEnd(req ServiceExecuteRequest, meta map[string]string, final harnesses.FinalData) {
	if sl == nil || sl.logger == nil {
		return
	}
	sl.endOnce.Do(func() {
		sl.endWrote.Store(true)
		end := session.SessionEndData{
			Status:           harnessStatusToCoreStatus(final.Status),
			Output:           final.FinalText,
			Tokens:           finalUsageToCoreTokens(final.Usage),
			DurationMs:       final.DurationMS,
			SelectedRoute:    req.SelectedRoute,
			SelectedEndpoint: sl.decision.Endpoint,
			Sticky: session.RoutingStickyState{
				KeyPresent:     req.CorrelationID != "",
				Assignment:     sl.decision.Sticky.Assignment,
				ServerInstance: sl.decision.Sticky.ServerInstance,
				Reason:         sl.decision.Sticky.Reason,
			},
			Utilization: session.RoutingUtilizationState{
				Source:         sl.decision.Utilization.Source,
				Freshness:      sl.decision.Utilization.Freshness,
				ActiveRequests: sl.decision.Utilization.ActiveRequests,
				QueuedRequests: sl.decision.Utilization.QueuedRequests,
				MaxConcurrency: sl.decision.Utilization.MaxConcurrency,
				CachePressure:  sl.decision.Utilization.CachePressure,
				ObservedAt:     sl.decision.Utilization.ObservedAt,
			},
			RequestedHarness:  req.Harness,
			ResolvedHarness:   "",
			HarnessSource:     harnessSource(req),
			RequestedModel:    req.Model,
			RequestedModelRef: req.ModelRef,
			ResolvedModelRef:  req.ResolvedModelRef,
			Reasoning:         req.Reasoning,
			Metadata:          meta,
			Error:             final.Error,
		}
		if final.CostUSD > 0 {
			cost := final.CostUSD
			end.CostUSD = &cost
		}
		if final.RoutingActual != nil {
			end.ResolvedHarness = final.RoutingActual.Harness
			end.Model = final.RoutingActual.Model
			end.SelectedProvider = final.RoutingActual.Provider
			if final.RoutingActual.ServerInstance != "" {
				end.SelectedServerInstance = final.RoutingActual.ServerInstance
			}
			end.ResolvedModel = final.RoutingActual.Model
			end.AttemptedProviders = append([]string(nil), final.RoutingActual.FallbackChainFired...)
			if len(end.AttemptedProviders) > 1 {
				end.FailoverCount = len(end.AttemptedProviders) - 1
			}
		}
		if end.SelectedServerInstance == "" {
			end.SelectedServerInstance = sl.decision.ServerInstance
		}
		sl.logger.Emit(agentcore.EventSessionEnd, end)
	})
}

// writeEvent persists a raw agent event to the session log. Used by the
// native loop callback to capture llm.request / llm.response / tool.call /
// compaction.* events so kept-sandbox bundles preserve a complete trace
// for benchmark reruns and post-mortem debugging. session.start and
// session.end are skipped because writeStart/writeEnd own those records and
// enrich them with service-side routing fields the loop does not see.
func (sl *serviceSessionLog) writeEvent(ev agentcore.Event) {
	if sl == nil || sl.logger == nil {
		return
	}
	switch ev.Type {
	case agentcore.EventSessionStart, agentcore.EventSessionEnd,
		agentcore.EventOverride, agentcore.EventRejectedOverride:
		return
	}
	sl.logger.Write(ev)
}

// writeOverrideEvent persists an override or rejected_override payload to
// the session log so windowed reporting (UsageReport, ADR-006 §5) can
// recompute routing-quality across restarts and beyond the in-memory
// ring's bounded retention. eventType is one of ServiceEventTypeOverride
// / ServiceEventTypeRejectedOverride.
func (sl *serviceSessionLog) writeOverrideEvent(eventType string, payload ServiceOverrideData) {
	if sl == nil || sl.logger == nil {
		return
	}
	payload.SessionID = sl.sessionID
	sl.logger.Emit(agentcore.EventType(eventType), payload)
}

// close flushes the underlying file. Safe to call multiple times.
func (sl *serviceSessionLog) close() {
	if sl == nil || sl.logger == nil {
		return
	}
	sl.closeOnce.Do(func() {
		_ = sl.logger.Close()
	})
}

// endWritten reports whether writeEnd has already recorded a terminal event.
func (sl *serviceSessionLog) endWritten() bool {
	if sl == nil {
		return false
	}
	return sl.endWrote.Load()
}

// persistRejectedOverride writes a session.start + rejected_override pair
// to a freshly-opened session log for sessionID. Used by Execute's
// pre-dispatch rejection branch, which never reaches runExecute and so
// never goes through the normal openSessionLog path. Without this,
// rejected_override events are invisible to UsageReport (which scans
// session logs over a --since window).
//
// The session.start is required by ScanRoutingQuality, which only counts
// log files that include one — and we want this rejection counted in
// TotalRequests so AutoAcceptanceRate reflects reality.
func (s *service) persistRejectedOverride(req ServiceExecuteRequest, sessionID string, payload ServiceOverrideData) {
	if req.SessionLogDir == "" || sessionID == "" {
		return
	}
	sl := s.openSessionLog(req, RouteDecision{}, sessionID)
	if sl == nil || sl.logger == nil {
		return
	}
	defer sl.close()
	sl.writeOverrideEvent(ServiceEventTypeRejectedOverride, payload)
}

// providerTypeLabel maps a configured provider name ("local") to its provider
// type ("lmstudio") when available. Returns the input unchanged if no
// ServiceConfig is attached or the name is not configured. Callers use this
// to populate session-log Provider fields, which historically carry the
// provider *type* rather than the configured name.
func (s *service) providerTypeLabel(name string) string {
	if s == nil || s.opts.ServiceConfig == nil || name == "" {
		return name
	}
	entry, ok := s.opts.ServiceConfig.Provider(name)
	if !ok || entry.Type == "" {
		return name

package routing

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

// Request is the routing input. All fields are optional except at least
// one of {Profile, ModelRef, Model, Harness, Provider} should be set
// (otherwise the engine has nothing to disambiguate on).
//
// Provider is present from day one (fixes ddx-8610020e — no soft-preference
// dropping).
type Request struct {
	Profile            string // "cheap" | "standard" | "smart"
	ModelRef           string // catalog alias (e.g. "qwen/qwen3.6")
	Model              string // exact concrete model pin
	Provider           string // exact provider pin; constrains routing to one provider identity
	Harness            string // hard preference; constrains routing to one harness
	Reasoning          string // public reasoning scalar
	Permissions        string // "safe" | "supervised" | "unrestricted"
	ProviderPreference string // "local-first" | "subscription-first" | "local-only" | "subscription-only"

	// EstimatedPromptTokens, when > 0, drives context-window gating.
	EstimatedPromptTokens int

	// RequiresTools, when true, requires the candidate to support tool calling.
	RequiresTools bool
	MinPower      int
	MaxPower      int
}

const (
	ProviderPreferenceLocalFirst        = "local-first"
	ProviderPreferenceSubscriptionFirst = "subscription-first"
	ProviderPreferenceLocalOnly         = "local-only"
	ProviderPreferenceSubscriptionOnly  = "subscription-only"
)

// MinContextWindow returns the minimum context window the request requires,
// derived from EstimatedPromptTokens with a safety margin.
func (r Request) MinContextWindow() int {
	if r.EstimatedPromptTokens <= 0 {
		return 0
	}
	// 1.25x safety margin for response tokens + tool overhead.
	return r.EstimatedPromptTokens + r.EstimatedPromptTokens/4
}

const (
	QuotaTrendUnknown    = "unknown"
	QuotaTrendHealthy    = "healthy"
	QuotaTrendBurning    = "burning"
	QuotaTrendExhausting = "exhausting"
)

// HarnessEntry is the harness-side input the caller (service) supplies.
// It is the routing engine's view of a registered harness; the engine does
// not import the harnesses package directly to keep the dependency narrow.
type HarnessEntry struct {
	Name                string
	Surface             string
	CostClass           string
	IsLocal             bool
	IsSubscription      bool
	IsHTTPProvider      bool
	AutoRoutingEligible bool
	TestOnly            bool
	ExactPinSupport     bool
	DefaultModel        string
	SupportedModels     []string
	SupportedReasoning  []string
	MaxReasoningTokens  int
	SupportedPerms      []string
	SupportsTools       bool

	// Available reflects the harness's discovered availability.
	Available bool

	// QuotaOK / QuotaPercentUsed reflect live quota state (when applicable).
	// SubscriptionOK gates subscription harnesses at the eligibility level:
	// when false, the candidate is ineligible regardless of score.
	QuotaOK          bool
	QuotaPercentUsed int
	QuotaStale       bool
	QuotaTrend       string // unknown|healthy|burning|exhausting
	QuotaReason      string
	SubscriptionOK   bool // false = hard gate; true = score-based demotion

	// InCooldown marks the entire harness as being in a failure cooldown.
	// When true the harness is demoted in score (via candidateInternal.InCooldown)
	// but not hard-rejected, so it can still win when all other harnesses are
	// also unavailable.
	InCooldown bool

	// Providers is the list of providers this harness can dispatch to.
	// For subprocess harnesses (claude/codex) this is typically a single
	// vendor entry. For the native "fiz" harness it is the configured
	// list of HTTP providers.
	Providers []ProviderEntry
}

// ProviderEntry describes one provider available under a harness.
type ProviderEntry struct {
	Name               string
	BaseURL            string
	ServerInstance     string
	EndpointName       string
	EndpointBaseURL    string
	DefaultModel       string
	CostClass          string
	DiscoveredIDs      []string // models discovered via /v1/models or equivalent
	DiscoveryAttempted bool
	ContextWindows     map[string]int
	SupportsTools      bool

	// CostUSDPer1kTokens is the estimated blended USD cost per 1,000 tokens.
	// A zero value with CostSourceUnknown means the provider cost is unknown.
	CostUSDPer1kTokens float64
	// CostSource describes where CostUSDPer1kTokens came from: catalog,
	// subscription, user-config, or unknown.
	CostSource string

	// InCooldown reflects whether this provider is in a failure-cooldown window.
	InCooldown bool
}

const (
	// CostSourceCatalog means cost came from the model catalog.
	CostSourceCatalog = "catalog"
	// CostSourceSubscription means cost came from subscription quota pricing.
	CostSourceSubscription = "subscription"
	// CostSourceUnknown means no reliable cost estimate is available.
	CostSourceUnknown = "unknown"
	// CostSourceUserConfig means cost came from explicit user configuration.
	CostSourceUserConfig = "user-config"
)

// Decision is the routing engine's output: the picked candidate plus the
// full ranked list (including rejected ones with rejection reasons).
type Decision struct {
	Harness        string
	Provider       string
	Endpoint       string
	ServerInstance string
	Model          string
	Reason         string
	Candidates     []Candidate
}

// Candidate is one ranked routing option.
type Candidate struct {
	Harness            string
	Provider           string
	Endpoint           string
	ServerInstance     string
	Model              string
	Score              float64
	CostUSDPer1kTokens float64
	CostSource         string
	Power              int
	Eligible           bool
	Reason             string

	// FilterReason is the typed disqualification category, set at the
	// rejection site that decided why this candidate is ineligible.
	// Empty for eligible candidates. Service-layer code maps this to the
	// public FilterReason* string constants without parsing free-form
	// Reason text.
	FilterReason FilterReason

	// LatencyMS, SuccessRate, and CostClass expose the score-component
	// inputs so callers can render per-axis explanations alongside the
	// final Score. Zero / negative values mean unknown (see Inputs docs).
	LatencyMS   float64
	SuccessRate float64
	CostClass   string
	SpeedTPS    float64

	QuotaOK          bool
	QuotaPercentUsed int
	QuotaTrend       string
}

// FilterReason categorizes why a routing candidate was disqualified.
// The zero value (empty string) means the candidate is eligible.
type FilterReason string

const (
	// FilterReasonEligible is the zero value for an eligible candidate.
	FilterReasonEligible FilterReason = ""
	// FilterReasonContextTooSmall: candidate's context window is below the
	// request's MinContextWindow().
	FilterReasonContextTooSmall FilterReason = "context_too_small"
	// FilterReasonNoToolSupport: request needs tool calling but candidate
	// does not support it.
	FilterReasonNoToolSupport FilterReason = "no_tool_support"
	// FilterReasonReasoningUnsupported: candidate cannot satisfy the
	// requested reasoning policy.
	FilterReasonReasoningUnsupported FilterReason = "reasoning_unsupported"
	// FilterReasonUnhealthy: harness/provider is unavailable, in cooldown,
	// out of quota, or excluded by a hard provider-preference gate.
	FilterReasonUnhealthy FilterReason = "unhealthy"
	// FilterReasonScoredBelowTop: catch-all for ineligibility that does
	// not fit a more specific category (also used for capability
	// mismatches such as permissions/model-pin/exact-pin and for model
	// resolution failures).
	FilterReasonScoredBelowTop FilterReason = "scored_below_top"
	// FilterReasonPinMismatch: candidate was rejected because it does not
	// satisfy an explicit caller pin such as Provider.
	FilterReasonPinMismatch FilterReason = "pin_mismatch"
	// FilterReasonPowerMissing: automatic routing requires catalog power
	// metadata, but the candidate model is unknown or has zero power.
	FilterReasonPowerMissing FilterReason = "power_missing"
	// FilterReasonBelowMinPower: candidate model power is below req.MinPower.
	FilterReasonBelowMinPower FilterReason = "below_min_power"
	// FilterReasonAboveMaxPower: candidate model power is above req.MaxPower.
	FilterReasonAboveMaxPower FilterReason = "above_max_power"
	// FilterReasonExactPinOnly: catalog marks the model as only eligible for
